def week_counts(days: list[int]) -> dict[int, int]:
    totals = defaultdict(int)
    for day in days:
        if day == 1 or day == 7:
            totals[1] += 1
        elif day == 2 or day == 6:
            totals[2] += 1
        elif day == 3 or day == 5:
            totals[3] += 1
        else:
            totals[4] += 1
    return dict(totals)
