def cheapest_dish(codes: list[str]) -> str:
    menu = {"code1": "dish1", "code2": "dish2", "code3": "dish3"}
    valid_codes = [code for code in codes if code in menu]
    if not valid_codes:
        return ""
    return min(valid_codes, key=lambda x: menu[x])
